    }

    expect(() =>
      parseNativeContentSnapshotManifest({
        ...base,
        omitted: [{ path: '.', size: null, type: 'directory', reason: 'git-selection-changed' }],
        omittedCount: 1,
        capture: {
          provider: 'git',
          gitSelection: {
            ...gitSelection,
            status: 'changed',
