  it('matches snapshot globs without catastrophic backtracking', () => {
    const matcher = compileNativeSnapshotPattern(`${'**/'.repeat(8)}target.ts`);
    const startedAt = performance.now();

    expect(matcher(`${'nested/'.repeat(80)}missing.ts`)).toBe(false);
    expect(performance.now() - startedAt).toBeLessThan(100);
  });

  it('stops snapshot glob matching cooperatively when its budget expires', () => {
    const matcher = compileNativeSnapshotPattern('**') as (
      relative: string,
      hasBudget?: () => boolean,
    ) => boolean;
    let budgetChecks = 0;

    expect(
      matcher('x'.repeat(4_096), () => {
        budgetChecks += 1;
        return budgetChecks === 1;
      }),
    ).toBe(false);
    expect(budgetChecks).toBeGreaterThan(1);
  });

  it.each([
    ['src/**/*.ts', 'src/index.ts', true],
    ['src/**/*.ts', 'src/nested/index.ts', true],
    ['src/**/*.ts', 'src/nested/index.js', false],
    ['assets/**', 'assets/icons/logo.svg', true],
    ['?.md', 'a.md', true],
    ['?.md', 'docs/a.md', false],
  ])('matches snapshot glob %s against %s', (pattern, relativePath, expected) => {
    expect(compileNativeSnapshotPattern(pattern)(relativePath)).toBe(expected);
  });

  it('covers literal, wildcard, slash-sensitive, and invalid snapshot patterns', () => {
    const cases: Array<[string, string, boolean]> = [
      ['src/file.ts', 'src/file.ts', true],
      ['src/file.ts', 'src/other.ts', false],
      ['src/?.ts', 'src/a.ts', true],
      ['src/?.ts', 'src/.ts', false],
      ['src/?.ts', 'src/a/b.ts', false],
      ['src/*.ts', 'src/file.ts', true],
      ['src/*.ts', 'src/nested/file.ts', false],
      ['**/*.ts', 'file.ts', true],
      ['**/*.ts', 'src/nested/file.ts', true],
      ['src/**', 'src/nested/file.ts', true],
      ['src/**', 'other/file.ts', false],
      ['**', 'a/b/c.ts', true],
    ];
    for (const [pattern, value, expected] of cases) {
      expect(compileNativeSnapshotPattern(pattern)(value), `${pattern} -> ${value}`).toBe(expected);
    }
    expect(compileNativeSnapshotPattern('**/*')('src/file.ts', () => false)).toBe(false);
    for (const pattern of ['', '../outside', 'a\\b', 'a\0b']) {
      expect(() => compileNativeSnapshotPattern(pattern)).toThrow();
    }
  });

  it('retains a deterministic hash/ref for omissions beyond the recorded output budget', async () => {
    await Promise.all(
      Array.from({ length: 1_003 }, (_, index) =>
        fs.writeFile(
          path.join(projectRoot, `overflow-${index.toString().padStart(4, '0')}.txt`),
          'x',
        ),
      ),
    );
    const options = {
      limits: { maxFiles: 1, maxFileBytes: 1, maxTotalBytes: 1 },
    } as const;

    const first = await createNativeContentSnapshot(paths, options);
    const second = await createNativeContentSnapshot(paths, options);

    expect(first.omittedCount).toBe(1_002);
    expect(first.omitted).toHaveLength(1_000);
    expect(first.omissionOverflow).toMatchObject({
      count: 2,
      hash: expect.stringMatching(/^[a-f0-9]{64}$/u),
      ref: expect.stringMatching(/^native-snapshot:\/\/omitted-overflow\/[a-f0-9]{64}$/u),
    });
    expect(second.omissionOverflow).toEqual(first.omissionOverflow);
    const serialized = JSON.stringify(first);
    expect(serialized).not.toContain('overflow-1001.txt');
    expect(serialized).not.toContain('overflow-1002.txt');
  });

  it('keeps every entry regardless of the serialized manifest size', async () => {
    const files = Array.from({ length: 40 }, (_, index) =>
