        expect(snapshot.entries.some((entry) => entry.path === 'a.ts')).toBe(true);
        expect(snapshot.omitted).toEqual([]);
        expect(openSpy.mock.calls.some(([file]) => String(file).endsWith('file.ts'))).toBe(false);
