}

describe('Native check owner recovery', () => {
  it('recognizes completed receipt reuse without a child but keeps an unregistered launch unknown', async () => {
    const directory = await root();
    const { run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    registration.execution.checks = [
      {
        id: 'once',
        status: 'passed',
        reusedFrom: { actionId: 'original', attempt: 1, candidateId: 'candidate', checkId: 'once' },
      },
    ];
    registration.execution.phase = 'completed';
    await registration.save();
    expect(
      (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].quiescent,
    ).toBe(false);
    registration.execution.terminationUnconfirmed = false;
    await registration.save();
    await registration.release();
    expect(
      (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].quiescent,
    ).toBe(true);
    registration.execution.checks = [{ id: 'once', status: 'passed' }];
    await registration.save();
    expect(
      (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].quiescent,
    ).toBe(false);
  });
  it.each(['SIGTERM', 'SIGKILL'] as const)(
    'stops checks and their descendants when their actual owner receives %s',
    async (signal) => {
      const directory = await root();
      const started = path.join(directory, 'started');
      const marker = path.join(directory, 'late');
      const bundle = path.join(directory, 'owner.cjs');
      const grandchild =
        "setTimeout(() => require('node:fs').writeFileSync(process.argv[1], 'late'), 800); setTimeout(() => process.exit(0), 1300)";
      const command = `require('node:fs').writeFileSync(process.argv[1], String(process.pid)); require('node:child_process').spawn(process.execPath, ['-e', ${JSON.stringify(grandchild)}, process.argv[2]], { stdio: 'ignore' }); setTimeout(() => process.exit(0), 1600)`;
      await build({
        stdin: {
          contents: `const { executeNativeCheck } = require('./domains/comet-native/native-check-executor.ts'); executeNativeCheck({projectRoot:process.env.COMET_TEST_ROOT,runtimeDir:require('node:path').join(process.env.COMET_TEST_ROOT,'runtime'),operationId:'owner',plan:{id:'check',name:'owner',executable:process.execPath,argv:['-e',${JSON.stringify(command)},process.env.COMET_TEST_STARTED,process.env.COMET_TEST_MARKER],cwdRef:'.',timeoutMs:5000,repeatable:false}}).catch(() => process.exitCode = 1);`,
          resolveDir: process.cwd(),
        },
        outfile: bundle,
        bundle: true,
        platform: 'node',
        format: 'cjs',
        logLevel: 'silent',
      });
      const owner = spawn(process.execPath, [bundle], {
        stdio: 'ignore',
        env: {
          ...process.env,
          COMET_TEST_ROOT: directory,
          COMET_TEST_STARTED: started,
          COMET_TEST_MARKER: marker,
        },
      });
      processes.push(owner);
      await waitForCondition(() => exists(started), 'check did not start', 5000);
      owner.kill(signal);
      await waitForProcessExit(owner);
      await sleep(1050);
      expect(await exists(marker)).toBe(false);
    },
  );

  it('keeps its deadline when the owner event loop cannot run its timeout timer', async () => {
    const directory = await root();
    const marker = path.join(directory, 'timer-late');
    const started = path.join(directory, 'timer-started');
    const bundle = path.join(directory, 'blocked-owner.cjs');
    const command =
      "require('node:fs').writeFileSync(process.argv[1], 'started'); setTimeout(() => require('node:fs').writeFileSync(process.argv[2], 'late'), 5500); setTimeout(() => process.exit(0), 8000)";
    await build({
      stdin: {
        contents: `const { executeNativeCheck } = require('./domains/comet-native/native-check-executor.ts'); executeNativeCheck({projectRoot:process.env.COMET_TEST_ROOT,runtimeDir:require('node:path').join(process.env.COMET_TEST_ROOT,'runtime'),operationId:'blocked-owner',plan:{id:'check',name:'blocked owner',executable:process.execPath,argv:['-e',${JSON.stringify(command)},process.env.COMET_TEST_STARTED,process.env.COMET_TEST_MARKER],cwdRef:'.',timeoutMs:5000,repeatable:false}}).catch(() => {}); const poll=setInterval(()=>{if(require('node:fs').existsSync(process.env.COMET_TEST_STARTED)){clearInterval(poll);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,6000)}},25);`,
        resolveDir: process.cwd(),
      },
      outfile: bundle,
      bundle: true,
      platform: 'node',
      format: 'cjs',
      logLevel: 'silent',
    });
    const owner = spawn(process.execPath, [bundle], {
      stdio: 'ignore',
      env: {
        ...process.env,
        COMET_TEST_ROOT: directory,
        COMET_TEST_STARTED: started,
        COMET_TEST_MARKER: marker,
      },
    });
    processes.push(owner);
    await waitForCondition(() => exists(started), 'check did not start', 5000);
    await sleep(6500);
    expect(await exists(marker)).toBe(false);
    await waitForProcessExit(owner);
  });

  it('does not launch the command before registration and bounds a stuck registration', async () => {
    const directory = await root();
    const marker = path.join(directory, 'unregistered-side-effect');
    const started = Date.now();
    await expect(
      executeNativeCheck({
        projectRoot: directory,
        runtimeDir: path.join(directory, 'runtime'),
        operationId: 'register',
        plan: {
          id: 'check',
          name: 'check',
          executable: process.execPath,
          argv: ['-e', "require('node:fs').writeFileSync(process.argv[1], 'bad')", marker],
          cwdRef: '.',
          timeoutMs: 150,
          repeatable: false,
        },
        onSpawn: async () => new Promise(() => {}),
      }),
    ).rejects.toThrow(/登记.*时限/u);
    expect(Date.now() - started).toBeLessThan(1500);
    expect(await exists(marker)).toBe(false);
  });

  it('kills background descendants before reporting their parent command complete', async () => {
    const directory = await root();
    const marker = path.join(directory, 'background');
    const grandchild =
      "setTimeout(() => require('node:fs').writeFileSync(process.argv[1], 'bad'), 500)";
    const result = await executeNativeCheck({
      projectRoot: directory,
      runtimeDir: path.join(directory, 'runtime'),
      operationId: 'background',
      plan: {
        id: 'check',
        name: 'check',
        executable: process.execPath,
        argv: [
          '-e',
          `require('node:child_process').spawn(process.execPath, ['-e', ${JSON.stringify(grandchild)}, process.argv[1]], { stdio: 'ignore' }).unref()`,
          marker,
        ],
        cwdRef: '.',
        timeoutMs: 2000,
        repeatable: false,
      },
    });
    expect(result.status).toBe('passed');
    await sleep(650);
    expect(await exists(marker)).toBe(false);
  });

  it('does not replay a check after its supervisor is killed before completion', async () => {
    const directory = await root();
    const { runtime, run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    const started = path.join(directory, 'started');
    const supervisor = spawnOwnedCommand(
      process.execPath,
      [
        '-e',
        `require('node:fs').writeFileSync(${JSON.stringify(started)}, String(process.pid)); setTimeout(() => process.exit(0), 25000)`,
      ],
      { cwd: directory, timeoutMs: 10000 },
    );
    processes.push(supervisor.child);
    await registration.register('check', { instanceId: supervisor.instanceId });
    supervisor.start();
    await waitForCondition(() => exists(started), 'check did not start');
    supervisor.child.kill('SIGKILL');
    await waitForProcessExit(supervisor.child);
    await registration.release();
    const checkPid = Number(await fs.readFile(started, 'utf8'));
    const checkIdentity = await readProcessIdentity(checkPid);
    try {
      if (process.platform !== 'win32') expect(checkIdentity).not.toBeNull();
      const status = (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0];
      expect(status.processBoundary).toBe('command');
      expect(status.process).toBe('unknown');
      if (process.platform !== 'win32')
        expect(await readProcessIdentity(checkPid)).toBe(checkIdentity);
      expect(status.quiescent).toBe(false);
      await expect(
        createNativeSdkCheckExecution({
          projectRoot: directory,
          run,
          action,
          candidateId: 'candidate',
          plansHash: 'plans',
        }),
      ).rejects.toMatchObject({ code: 'EEXIST' });
      // 进程仍活着时不得依赖原监管器 PID 消失释放工作区。
      expect((await runtime.inspect(run.runId)).actions[0].attempt).toBe(1);
    } finally {
      if (checkIdentity && (await readProcessIdentity(checkPid)) === checkIdentity) {
        try {
          process.kill(checkPid, 'SIGKILL');
        } catch {
          /* 原检查进程已退出 */
        }
      }
    }
    await waitForCondition(
      async () => (await inspectProcessTreeLiveness(supervisor.child.pid!, undefined)) === 'dead',
      'process group did not stop',
    );
  });

  it('records owner death as unknown while preserving claim and refuses overwrite across attempts', async () => {
    const directory = await root();
    const { runtime, run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    const owner = spawn(process.execPath, ['-e', 'setTimeout(() => {}, 10000)'], {
      stdio: 'ignore',
    });
    processes.push(owner);
    await registration.save();
    await registration.release();
    owner.kill('SIGKILL');
    await waitForProcessExit(owner);
    const recovered = await recoverNativeSdkChecks(directory, run, runtime);
    expect(recovered.actions[0]).toMatchObject({
      status: 'unknown',
      claim: action.claim,
      attempt: 1,
    });
    const again = await recoverNativeSdkChecks(directory, recovered, runtime);
    expect(again.revision).toBe(recovered.revision);
    await expect(
      runtime.retry({ runId: run.runId, actionId: action.id, attempt: 1 }),
    ).rejects.toMatchObject({ code: 'RECONCILIATION_REQUIRED' });
    const retried = await runtime.retry({
      runId: run.runId,
      actionId: action.id,
      attempt: 1,
      reconciliation: { resolution: 'not-executed', evidence: 'unsupported assertion' },
    });
    const next = retried.actions[0];
    const claimed = await runtime.claim({
      runId: run.runId,
      actionId: next.id,
      attempt: next.attempt,
      inputHash: next.inputHash,
      executorId: 'comet-native-checks',
      claimToken: 'another-claim',
    });
    await expect(
      createNativeSdkCheckExecution({
        projectRoot: directory,
        run: claimed,
        action: claimed.actions[0],
        candidateId: 'candidate',
        plansHash: 'plans',
      }),
    ).rejects.toMatchObject({ code: 'EEXIST' });
  });

  it('persists cancellation before a delayed executor has registered so it cannot launch', async () => {
    const directory = await root();
    const { run, action } = await claimedRun();
    expect(
      (await terminateNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].phase,
    ).toBe('missing');
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    await expect(registration.assertNotStopped()).rejects.toThrow(/取消/u);
    await expect(registration.register('delayed', process.pid)).rejects.toThrow(/取消/u);
    expect(registration.execution.child).toBeUndefined();
  });
});

