        [
          '-c',
          'user.name=Comet Test',
          '-c',
          'user.email=comet-test@example.invalid',
          'commit',
          '-m',
          'archive example',
        ],
        { cwd: projectRoot },
      );
      const commit = execFileSync('git', ['rev-parse', 'HEAD'], {
