async function fixture(profile: 'hotfix' | 'tweak', legacy = false, completed = true) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-preset-scope-'));
  roots.push(root);
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
  execFileSync(
    'git',
    [
      '-c',
      'user.name=Test',
      '-c',
      'user.email=test@example.invalid',
      'commit',
      '--allow-empty',
      '-m',
      'base',
    ],
    { cwd: root, stdio: 'ignore' },
  );
  const cli = async (...args: string[]) =>
    JSON.parse(
      (
        await runClassicCli([args[0], '--json', ...args.slice(1)], undefined, {
          projectRoot: root,
          invocationCwd: root,
        })
      ).stdout!,
    );
  const ok = async (...args: string[]) => {
    const result = await cli(...args);
    expect(result.exitCode, JSON.stringify(result)).toBe(0);
    return result.data;
  };
  await ok('state', 'init', 'example', profile, '--isolation', 'current');
  if (legacy) {
    const store = createClassicSdkStateStore(root);
    const run = (await store.read('example'))!;
    const workflow = structuredClone(classicSdkRevisionApplication(profile).workflow);
    const step = workflow.steps[`${profile}.build.execute`];
    delete (step.outputSchema as { properties: Record<string, unknown> }).properties
      .requirementsEvidence;
    delete step.validator;
    const definition = defineWorkflow(workflow);
    const hash = hashRuntimeValue(definition);
    const previous = structuredClone(run);
    previous.workflow.hash = hash;
    previous.definitionHashes[JSON.stringify([definition.id, definition.version])] = hash;
    previous.revision++;
    expect(await store.compareAndSwap(run.runId, run.revision, previous)).toBe(true);
  }
  const directory = path.join(root, 'openspec/changes/example');
  const proposal = '# Proposal\nFix the greeting typo without changing behavior.\n';
  await fs.writeFile(path.join(directory, 'proposal.md'), proposal);
  await fs.writeFile(
    path.join(directory, 'design.md'),
    '# Design\nPreserve the existing behavior.\n',
  );
  await fs.writeFile(path.join(directory, 'tasks.md'), '- [ ] Fix the greeting typo\n');
  const opened = await ok('guard', 'example', 'open');
  await ok('guard', 'example', 'open', '--apply', '--approval-hash', opened.approvalHash);
  if (completed)
    await fs.writeFile(path.join(directory, 'tasks.md'), '- [x] Fix the greeting typo\n');
  const check = ['--apply', '--', process.execPath, '-e', 'process.exit(0)'];
  return { root, directory, proposal, cli, ok, check };
}

describe.each(['hotfix', 'tweak'] as const)('%s approved scope', (profile) => {
  it('allows public task ID assignment and completion without another scope approval', async () => {
    const { ok, check } = await fixture(profile, false, false);
    const listed = await ok('state', 'tasks', 'example', '--assign-ids');
    await ok('state', 'task-complete', 'example', listed.tasks[0].id, '--expect', listed.revision);
    expect((await ok('guard', 'example', 'build', ...check)).phase).toBe('verify');
  });

  it('reconfirms actual requirement revisions explicitly in Build and Verify', async () => {
    const { root, directory, cli, ok, check } = await fixture(profile);
    const approve = async (reason: string) => {
      const proposal = await ok('state', 'propose-escalation', 'example', '--reason', reason);
      const before = (await inspectClassicSdkRun(root, 'example')).run;
      expect((await cli('guard', 'example', 'build', ...check)).exitCode).not.toBe(0);
      expect((await inspectClassicSdkRun(root, 'example')).run).toEqual(before);
      await ok(
        'state',
        'decide-escalation',
        'example',
        '--proposal-hash',
        proposal.wait.proposalHash,
        '--choice',
        'continue',
      );
    };
    await fs.writeFile(
      path.join(directory, 'proposal.md'),
      '# Proposal\nFix the typo and punctuation.\n',
    );
    await approve('Fixture user approves adding punctuation.');
    await fs.writeFile(path.join(directory, 'tasks.md'), '- [x] Fix typo and punctuation\n');
    expect((await ok('guard', 'example', 'build', ...check)).phase).toBe('verify');
    const before = (await inspectClassicSdkRun(root, 'example')).run;
    await ok('state', 'continue-build', 'example', '--expected-revision', String(before.revision));
    await fs.appendFile(
      path.join(directory, 'proposal.md'),
      'Also improve greeting capitalization.\n',
    );
    await approve('Fixture user approves the capitalization revision.');
    expect((await ok('guard', 'example', 'build', ...check)).phase).toBe('verify');
    const report = 'docs/superpowers/reports/example.md';
    await fs.mkdir(path.dirname(path.join(root, report)), { recursive: true });
    await fs.writeFile(
      path.join(root, report),
      '# Verification\nThe revised greeting checks passed.\n',
    );
    expect((await ok('guard', 'example', 'verify', '--report', report, ...check)).phase).toBe(
      'archive',
    );
  });
  it('upgrades a known previous definition without rewriting completed Actions after neutral edits', async () => {
    const { root, directory, proposal, cli, ok, check } = await fixture(profile, true);
    const legacy = await inspectClassicSdkRun(root, 'example');
    const action = legacy.run.actions.find((action) => action.status === 'pending')!;
    await legacy.runtime.claim({
      runId: 'example',
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'comet-classic-state',
      claimToken: 'legacy-scope',
    });
    const requested = await legacy.runtime.recordOutcome({
      runId: 'example',
      outcome: {
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        claimToken: 'legacy-scope',
        outcomeId: 'legacy-scope-proposal',
        status: 'succeeded',
        output: {
          event: 'escalation-requested',
          proposal: 'Continue the unchanged approved scope.',
        },
      },
    });
    const wait = requested.waits.find((wait) => wait.status === 'pending')!;
    await fs.appendFile(
      path.join(directory, 'proposal.md'),
      '<!-- Agent clarified the same scope. -->\n',
    );
    await ok(
      'state',
      'decide-escalation',
      'example',
      '--proposal-hash',
      wait.proposalHash,
      '--choice',
      'continue',
    );
    const before = (await inspectClassicSdkRun(root, 'example')).run;
    await fs.appendFile(
      path.join(directory, 'proposal.md'),
      'Also correct greeting punctuation.\n',
    );
    const proposed = await ok(
      'state',
      'propose-escalation',
      'example',
      '--reason',
      'Include punctuation.',
    );
    const after = (await inspectClassicSdkRun(root, 'example')).run;
    expect(after.workflow.hash).not.toBe(before.workflow.hash);
    expect(after.actions.slice(0, before.actions.length - 1)).toEqual(before.actions.slice(0, -1));
    await ok(
      'state',
      'decide-escalation',
      'example',
      '--proposal-hash',
      proposed.wait.proposalHash,
      '--choice',
      'continue',
    );
    expect((await ok('guard', 'example', 'build', ...check)).phase).toBe('verify');
  });
  it('keeps the original scope decision after neutral edits and rejects a stale SDK proposal', async () => {
    const { directory, cli, ok, check } = await fixture(profile);
    const proposal = '# Proposal\nCorrect greeting punctuation as well as the typo.\n';
    await fs.writeFile(path.join(directory, 'proposal.md'), proposal);
    await fs.writeFile(
      path.join(directory, 'tasks.md'),
      '- [ ] Correct greeting punctuation and typo\n',
    );
    const proposed = await ok(
      'state',
      'propose-escalation',
      'example',
      '--reason',
      'Include greeting punctuation in the same change.',
    );
    const hash = proposed.wait.proposalHash;
    await fs.appendFile(
      path.join(directory, 'proposal.md'),
      '<!-- Agent clarified the same scope. -->\n',
    );
    expect(
      (
        await cli(
          'state',
          'decide-escalation',
          'example',
          '--proposal-hash',
          '0'.repeat(64),
          '--choice',
          'continue',
        )
      ).exitCode,
    ).not.toBe(0);
    await fs.writeFile(path.join(directory, 'proposal.md'), proposal);
    await ok(
      'state',
      'decide-escalation',
      'example',
      '--proposal-hash',
      hash,
      '--choice',
      'continue',
    );
    await fs.writeFile(
      path.join(directory, 'tasks.md'),
      '- [x] Correct greeting punctuation and typo\n',
    );
    expect((await ok('guard', 'example', 'build', ...check)).phase).toBe('verify');
  });
});

import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { readCheckPolicy } from '../../../domains/comet-classic/classic-check-policy.js';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

// Retain public timeout behavior for persisted v1 managed-check Runs; v2 uses Agent reports.
vi.mock('../../../domains/comet-classic/classic-sdk-application.js', async (importOriginal) => {
  const actual =
    await importOriginal<
      typeof import('../../../domains/comet-classic/classic-sdk-application.js')
    >();
  return {
    ...actual,
    defineClassicAgentWorkflowApplication: actual.defineClassicWorkflowApplication,
  };
});

let root: string;
const identity = { argv: [process.execPath, 'check.cjs'], cwd: '.' };
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-check-defaults-'));
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
});
afterEach(async () => {
  await fs.rm(root, { recursive: true, force: true, maxRetries: 5 });
});
async function put(ref: string, text: string) {
  await fs.mkdir(path.dirname(path.join(root, ref)), { recursive: true });
  await fs.writeFile(path.join(root, ref), text);
}
async function invoke(...args: string[]) {
  const separator = args.indexOf('--');
  args.splice(separator < 0 ? args.length : separator, 0, '--json');
  const result = await runClassicCli(args, undefined, { invocationCwd: root });
  return { ...result, response: JSON.parse(result.stdout ?? '{}') };
}
async function cli(...args: string[]) {
  const result = await invoke(...args);
  expect(result.exitCode, result.stdout ?? result.stderr).toBe(0);
  return result.response.data;
}
async function prepare(runtime: 'compat' | 'sdk') {
  await cli('state', 'init', 'demo', 'tweak', '--runtime', runtime, '--isolation', 'current');
  await put('openspec/changes/demo/proposal.md', '# Proposal\nFix source.\n');
  await put('openspec/changes/demo/design.md', '# Design\nKeep public behavior.\n');
  await put('openspec/changes/demo/tasks.md', '- [x] Fix source <!-- comet-task:source -->\n');
  const open = await cli('guard', 'demo', 'open');
  await cli(
    'guard',
    'demo',
    'open',
    '--apply',
    ...(runtime === 'sdk' ? ['--approval-hash', open.approvalHash] : []),
  );
  if (runtime === 'sdk') await cli('state', 'complete-build', 'demo');
}
const policy = (command: Record<string, unknown>) =>
  put(
    '.comet/check-policy.json',
    JSON.stringify({ version: 2, commands: [{ ...identity, ...command }] }),
  );

it.each(['compat', 'sdk'] as const)(
  'applies project timeout to the public %s check run',
  async (runtime) => {
    await prepare(runtime);
    await fs.appendFile(path.join(root, '.comet/config.yaml'), '  check_timeout_ms: 25\n');
    const result = await invoke(
      'check',
      'run',
      'demo',
      'build',
      '--',
      process.execPath,
      '-e',
      // 保持命令存活到超时终止，避免它在 Windows taskkill 枚举期间自然退出。
      'setTimeout(() => {}, 20000)',
    );
    expect(result.exitCode, result.stdout).toBe(124);
    expect(result.response.data.timeoutMs).toBe(25);
  },
);

it.each(['compat', 'sdk'] as const)(
  'lets explicit CLI timeout override the project default for %s',
  async (runtime) => {
    await prepare(runtime);
    await fs.appendFile(path.join(root, '.comet/config.yaml'), '  check_timeout_ms: 1\n');
    const result = await invoke(
      'check',
      'run',
      'demo',
      'build',
      '--timeout-ms',
      '5000',
      '--',
      process.execPath,
      '-e',
      'setTimeout(() => {}, 50)',
    );
    expect(result.exitCode, result.stdout).toBe(0);
    expect(result.response.data.timeoutMs).toBe(5000);
  },
);

it.each([{ presets: ['unknown'] }, { presets: 'vite' }, { presets: [false] }])(
  'rejects invalid presets %j',
  async ({ presets }) => {
    await policy({ presets });
    await expect(readCheckPolicy(root, identity)).rejects.toThrow(/preset/iu);
  },
);

it('does not reuse a command executed under a different explicit timeout', async () => {
  await prepare('compat');
  const argv = [process.execPath, '-e', 'setTimeout(() => {}, 50)'];
  const first = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--local',
    '--timeout-ms',
    '5000',
    '--',
    ...argv,
  );
  expect(first.exitCode).toBe(0);
  const second = await invoke(
    'check',
    'run',
    'demo',
    'build',
    '--local',
    '--timeout-ms',
    '1',
    '--',
    ...argv,
  );
  expect(second.exitCode, second.stdout).toBe(124);
  expect(second.response.data.timeoutMs).toBe(1);
  expect(second.response.data.reused).not.toBe(true);
});

it('rerun preserves the previous resolved timeout rather than a changed project default', async () => {
  await prepare('compat');
  const configPath = path.join(root, '.comet/config.yaml');
  const initialConfig = await fs.readFile(configPath, 'utf8');
  await fs.writeFile(configPath, initialConfig + '  check_timeout_ms: 5000\n');
  const first = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--',
    process.execPath,
    '-e',
    'setTimeout(() => {}, 50)',
  );
  expect(first.timeoutMs).toBe(5000);
  await fs.writeFile(configPath, initialConfig + '  check_timeout_ms: 1\n');
  const rerun = await cli('check', 'rerun', 'demo', 'build');
  expect(rerun.timeoutMs).toBe(5000);
});
